'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId, useMemo, useRef, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import {
  CircleCheckIcon,
  TriangleAlertIcon,
  UndoIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { risePresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { Canvas } from './canvas';
import { shownNameOf, WORKFLOW_NAME, type Step } from './data';
import { problemsOf, problemsOfStep, stepOf } from './graph';
import { Inspector } from './inspector';
import { layoutOf, type Orientation } from './layout';
import {
  graphOf,
  INITIAL,
  LOOP_AFTER_MS,
  PUBLISH_MS,
  reducer,
  RESTING,
  SCRIPT,
  type PublishState,
} from './session';
import {
  BottomSheet,
  DEFAULT_WIDTH,
  isOwnEscape,
  ResizeHandle,
  SHEET_SHARE,
} from './side-panel';
import { useWidthBand, type WidthBand } from './use-width-band';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const PUBLISH_LABELS: Record<MorphState, string> = {
  idle: 'Publish',
  busy: 'Publishing',
  done: 'Published',
};

const MORPH_OF: Record<PublishState, MorphState> = {
  draft: 'idle',
  publishing: 'busy',
  live: 'done',
};

const CANVAS_HINT =
  'Tab moves through the steps. The arrow keys follow the connections. Enter opens a step in the inspector. Alt with an arrow key moves the step along the grid. Delete removes it, and Undo brings it back. The menu of a step connects it without dragging.';

type RowStyle = React.CSSProperties & { '--inspector': string };

type Status = 'problems' | 'ready' | 'live';

function orientationOf(band: WidthBand | null): Orientation {
  if (band === 'wide' || band === null) {
    return 'across';
  }
  return 'down';
}

function stepsWordOf(count: number) {
  if (count === 1) {
    return '1 step';
  }
  return `${count} steps`;
}

function wiresWordOf(count: number) {
  if (count === 1) {
    return '1 connection';
  }
  return `${count} connections`;
}

function problemWordOf(count: number) {
  if (count === 1) {
    return 'problem';
  }
  return 'problems';
}

function statusOf(problemCount: number, isLive: boolean): Status {
  if (problemCount > 0) {
    return 'problems';
  }
  if (isLive) {
    return 'live';
  }
  return 'ready';
}

function stageWordOf(isLive: boolean) {
  if (isLive) {
    return 'Live';
  }
  return 'Draft';
}

function stageVariantOf(isLive: boolean) {
  if (isLive) {
    return 'success';
  }
  return 'secondary';
}

function coveredOf(isSheetOpen: boolean) {
  if (isSheetOpen) {
    return SHEET_SHARE;
  }
  return 0;
}

function shownStepOf(step: Step | undefined, isOpen: boolean) {
  if (isOpen) {
    return step;
  }
  return undefined;
}

type ProblemStatusProps = {
  count: number;
  isLive: boolean;
};

function ProblemStatus({ count, isLive }: ProblemStatusProps) {
  const status = statusOf(count, isLive);

  return (
    <p className='flex h-8 items-center text-xs'>
      <Swap swapKey={status}>
        {status === 'problems' && (
          <span className='text-warning-foreground flex items-center gap-1.5 tabular-nums'>
            <TriangleAlertIcon className='size-3.5' />
            <MotionNumber value={count} />
            {problemWordOf(count)}
          </span>
        )}
        {status === 'ready' && (
          <span className='text-success-foreground flex items-center gap-1.5'>
            <CircleCheckIcon className='size-3.5' />
            Ready to publish
          </span>
        )}
      </Swap>
    </p>
  );
}

type UndoLineProps = {
  step: Step | undefined;
  onUndo: () => void;
  onDismiss: () => void;
};

/** It stays until it is used or dismissed: a timer would take the focus away with it. */
function UndoLine({ step, onUndo, onDismiss }: UndoLineProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = risePresenceOf(shouldReduceMotion);

  return (
    <AnimatePresence initial={false}>
      {step && (
        <motion.div
          key='undo'
          className='pointer-events-none absolute inset-x-3 top-3 flex justify-center'
          {...presence}
        >
          <div className='surface-raised pointer-events-auto flex h-9 max-w-full items-center gap-1 rounded-full ps-3.5 pe-1 text-[13px]'>
            <span className='min-w-0 truncate'>
              {shownNameOf(step)} removed
            </span>
            <Button
              type='button'
              variant='ghost'
              size='sm'
              data-undo
              onClick={onUndo}
              className='text-primary-ink rounded-full'
            >
              <UndoIcon />
              Undo
            </Button>
            <Button
              type='button'
              variant='ghost'
              size='icon-sm'
              aria-label='Dismiss'
              onClick={onDismiss}
              className='text-muted-foreground rounded-full'
            >
              <XIcon />
            </Button>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

/** It lies over the canvas without taking its presses, so the zoom control under it still works. */
function EmptyCanvas({ onRestore }: { onRestore: () => void }) {
  return (
    <div className='pointer-events-none absolute inset-0 flex flex-col items-center justify-center gap-3 p-6 text-center'>
      <p className='text-muted-foreground text-[13px]'>
        No step is left on the canvas
      </p>
      <Button
        type='button'
        variant='outline'
        size='sm'
        onClick={onRestore}
        className='pointer-events-auto'
      >
        Restore the sample workflow
      </Button>
    </div>
  );
}

export default function Workflows01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const rowRef = useRef<HTMLDivElement>(null);
  const band = useWidthBand(rowRef);
  const headingId = useId();
  const hintId = useId();
  const inspectorId = useId();
  const [inspectorWidth, setInspectorWidth] = useState(DEFAULT_WIDTH);
  const [round, setRound] = useState(0);
  const orientation = orientationOf(band);
  const layout = useMemo(
    () => layoutOf(state.steps, state.wires, orientation),
    [state.steps, state.wires, orientation]
  );
  const graph = graphOf(state);
  const problems = problemsOf(graph);
  const problemCount = problems.length;
  const selected = stepOf(state.steps, state.selectedId);
  const shownStep = shownStepOf(selected, state.isInspectorOpen);
  const isSheet = band === 'phone';
  const isPanel = band === 'compact' || band === 'wide';
  const isSheetOpen = isSheet && shownStep !== undefined;
  const isLive = state.publish === 'live';
  const isEmpty = state.steps.length === 0;
  const stageWord = stageWordOf(isLive);
  const canReplay = isFinished && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, state.notice);
  const stepsWord = stepsWordOf(state.steps.length);
  const wiresWord = wiresWordOf(state.wires.length);
  const rowStyle: RowStyle = { '--inspector': `${inspectorWidth}px` };

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /** After a refusal the focus goes to the field to fill, or to the inspector when a wire is missing. */
  function focusProblemLater() {
    requestAnimationFrame(() => {
      const root = ref.current;
      const field = root?.querySelector<HTMLElement>('[aria-invalid="true"]');
      const heading = root?.querySelector<HTMLElement>(
        '[data-inspector-heading]'
      );
      const target = field ?? heading;
      target?.focus();
    });
  }

  function open(id: string, isFromKeyboard: boolean) {
    act({ type: 'opened', id });
    if (isFromKeyboard) {
      focusLater('[data-inspector-heading]');
    }
  }

  function close() {
    act({ type: 'closed' });
    if (state.selectedId !== null) {
      focusLater(`[data-step-button="${state.selectedId}"]`);
    }
  }

  function remove(id: string) {
    act({ type: 'removed', id });
    focusLater('[data-undo]');
  }

  function undo() {
    const lost = state.removed;
    act({ type: 'undone' });
    if (lost) {
      focusLater(`[data-step-button="${lost.step.id}"]`);
    }
  }

  function dismissUndo() {
    act({ type: 'undoDismissed' });
    focusLater('[data-canvas-frame]');
  }

  function publish() {
    act({ type: 'publishStarted' });
    if (problemCount > 0) {
      focusProblemLater();
      return;
    }
    if (state.publish === 'draft') {
      schedule(() => act({ type: 'publishDone' }), PUBLISH_MS);
    }
  }

  /** A new round starts on a fresh canvas, so the view a person left does not hide the demonstration. */
  function replay() {
    restart();
    setRound((current) => current + 1);
  }

  function closeOnEscape(event: React.KeyboardEvent<HTMLElement>) {
    if (isOwnEscape(event)) {
      close();
    }
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container flex h-dvh min-h-[38rem] w-full flex-col overflow-hidden'
      >
        <div className='mx-auto flex min-h-0 w-full max-w-7xl flex-1 flex-col gap-3 p-3 @3xl:gap-4 @3xl:p-4'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
              <div className='flex items-center gap-2'>
                <h1 className='truncate text-lg font-semibold'>
                  {WORKFLOW_NAME}
                </h1>
                <Badge variant={stageVariantOf(isLive)}>
                  <Swap swapKey={stageWord}>{stageWord}</Swap>
                </Badge>
              </div>
              <p className='text-muted-foreground text-xs tabular-nums'>
                {stepsWord} · {wiresWord}
              </p>
            </div>
            <div className='flex flex-wrap items-center gap-x-3 gap-y-2'>
              <ReplayButton
                isShown={canReplay}
                onReplay={replay}
                label='Replay the demo'
              />
              <ProblemStatus count={problemCount} isLive={isLive} />
              <MorphButton
                type='button'
                state={MORPH_OF[state.publish]}
                labels={PUBLISH_LABELS}
                onClick={publish}
                className={pressedSolidOf(pressed === 'publish')}
              />
            </div>
          </header>

          <div ref={rowRef} style={rowStyle} className='flex min-h-0 flex-1'>
            <div className='group/canvas bg-foreground/[0.03] relative min-w-0 flex-1 overflow-hidden rounded-xl'>
              <Canvas
                key={round}
                isLaidOut={band !== null}
                label={`Canvas of ${WORKFLOW_NAME}`}
                subject='the workflow'
                hintId={hintId}
                inspectorId={inspectorId}
                steps={state.steps}
                graph={graph}
                problems={problems}
                layout={layout}
                orientation={orientation}
                selectedId={state.selectedId}
                isInspectorOpen={state.isInspectorOpen}
                covered={coveredOf(isSheetOpen)}
                wiring={state.wiring}
                isDemonstrating={isAutoplaying}
                pressed={pressed}
                onAction={act}
                onOpen={open}
                onRemove={remove}
              />
              <p id={hintId} className='sr-only'>
                {CANVAS_HINT}
              </p>
              {isEmpty && (
                <EmptyCanvas onRestore={() => act({ type: 'restored' })} />
              )}
              <UndoLine
                step={state.removed?.step}
                onUndo={undo}
                onDismiss={dismissUndo}
              />
              {isSheet && (
                <BottomSheet
                  id={inspectorId}
                  isOpen={isSheetOpen}
                  label='Step inspector'
                  onClose={close}
                >
                  {shownStep && (
                    <Inspector
                      step={shownStep}
                      graph={graph}
                      problems={problemsOfStep(problems, shownStep.id)}
                      headingId={headingId}
                      onAction={act}
                      onRemove={remove}
                      onClose={close}
                    />
                  )}
                </BottomSheet>
              )}
            </div>
            {isPanel && shownStep && (
              <>
                <ResizeHandle
                  width={inspectorWidth}
                  containerRef={rowRef}
                  onWidthChange={setInspectorWidth}
                />
                <aside
                  id={inspectorId}
                  aria-label='Step inspector'
                  onKeyDown={closeOnEscape}
                  className='bg-card hairline-ring ring-border flex w-(--inspector) max-w-[46%] shrink-0 flex-col rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-opacity duration-200 starting:opacity-0'
                >
                  <Inspector
                    step={shownStep}
                    graph={graph}
                    problems={problemsOfStep(problems, shownStep.id)}
                    headingId={headingId}
                    onAction={act}
                    onRemove={remove}
                    onClose={close}
                  />
                </aside>
              </>
            )}
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useEffect, useLayoutEffect, useRef, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { OUTPUT_IDS, type OutputId, type Step } from './data';
import {
  canConnect,
  neighbourOf,
  problemsOfStep,
  stepOf,
  type Graph,
  type Problem,
} from './graph';
import {
  draggedCellOf,
  GRID,
  moveOfKey,
  nudgedCellOf,
  stepAt,
  wirePathOf,
  type CanvasLayout,
  type Cell,
  type Orientation,
  type Point,
} from './layout';
import type { BuilderAction, Wire, Wiring } from './session';
import { StepCard, type Aim } from './step-card';
import { usePanZoom } from './use-pan-zoom';
import { HeldLayer, WireLayer } from './wires';
import { ZoomControl } from './zoom-control';

type Press = {
  kind: 'press';
  pointerId: number;
  stepId: string;
  origin: Cell;
  startX: number;
  startY: number;
  isTouch: boolean;
};

type Moving = {
  kind: 'move';
  pointerId: number;
  stepId: string;
  origin: Cell;
  startX: number;
  startY: number;
  cell: Cell;
};

type Wired = {
  kind: 'wire';
  pointerId: number;
  from: string;
  output: OutputId;
  aim: string | null;
};

/** What the pointers on the canvas are doing. A press has not yet chosen between a click, a move and a pan. */
type Gesture = { kind: 'pan' } | Press | Moving | Wired;

const MOUSE_SLOP = 4;

const TOUCH_SLOP = 8;

/** A finger held still this long on a step lifts it. A finger that moves first pans the canvas. */
const HOLD_MS = 220;

/** A wire lands on a step from this far around its card. */
const AIM_REACH = 14;

const FRAME = [
  'absolute inset-0 cursor-grab overflow-hidden rounded-xl outline-none select-none active:cursor-grabbing',
  'group-focus-within/canvas:touch-none',
].join(' ');

const GRID_LINES = [
  'pointer-events-none absolute inset-0 transition-opacity duration-200',
  '[--line:color-mix(in_oklab,var(--foreground)_8%,transparent)]',
  'bg-[linear-gradient(to_right,var(--line)_1px,transparent_1px),linear-gradient(to_bottom,var(--line)_1px,transparent_1px)]',
].join(' ');

function outputOf(value: string | undefined) {
  const output = OUTPUT_IDS.find((candidate) => candidate === value);
  return output ?? null;
}

function slopOf(isTouch: boolean) {
  if (isTouch) {
    return TOUCH_SLOP;
  }
  return MOUSE_SLOP;
}

function gridToneOf(isShown: boolean) {
  if (isShown) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

/** A held wire only lives while something holds it: a pointer, or the demonstration. */
function heldWiringOf(isHeld: boolean, wiring: Wiring | null) {
  if (isHeld) {
    return wiring;
  }
  return null;
}

function aimOf(held: Wiring | null, graph: Graph, stepId: string): Aim {
  if (!held) {
    return 'idle';
  }
  if (held.from === stepId) {
    return 'source';
  }
  if (held.to === stepId) {
    return 'aimed';
  }
  if (canConnect(graph, held.from, stepId)) {
    return 'open';
  }
  return 'closed';
}

/** The output a wire leaves: the one being held, or the one the demonstration is pressing. */
function heldOutputOf(
  stepId: string,
  held: Wiring | null,
  pressed: string | null
) {
  if (held?.from === stepId) {
    return held.output;
  }
  const output = OUTPUT_IDS.find(
    (candidate) => pressed === `port-${stepId}-${candidate}`
  );
  return output ?? null;
}

/** The demonstration has no pointer, so its wire is drawn from its port to the step it aims at. */
function demoPathOf(
  held: Wiring | null,
  layout: CanvasLayout<Wire>,
  orientation: Orientation
) {
  if (!held || held.to === null) {
    return null;
  }
  const from = layout.places[held.from]?.outputs[held.output];
  const to = layout.places[held.to]?.input;
  if (!from || !to) {
    return null;
  }
  return wirePathOf(from, to, orientation);
}

function boxOf(layout: CanvasLayout<Wire>, id: string | null) {
  if (id === null) {
    return null;
  }
  return layout.places[id]?.box ?? null;
}

function inputOf(layout: CanvasLayout<Wire>, id: string | null) {
  if (id === null) {
    return null;
  }
  return layout.places[id]?.input ?? null;
}

function heldIdOf(isHeld: boolean, id: string | null) {
  if (isHeld) {
    return id;
  }
  return null;
}

function clientPointOf(event: React.PointerEvent<HTMLDivElement>): Point {
  return { x: event.clientX, y: event.clientY };
}

/**
 * The canvas owns the wheel and the touch gestures while it holds the focus. Some browsers do not
 * give the focus to a pressed button, so the frame takes it first.
 */
function engage(frame: HTMLDivElement) {
  if (!frame.contains(document.activeElement)) {
    frame.focus({ preventScroll: true });
  }
}

export type CanvasProps = {
  /** False until the builder knows how wide it is, and so which way the flow reads. */
  isLaidOut: boolean;
  label: string;
  /** What Fit brings into view, for its accessible name. */
  subject: string;
  hintId: string;
  inspectorId: string;
  steps: Step[];
  graph: Graph;
  problems: Problem[];
  layout: CanvasLayout<Wire>;
  orientation: Orientation;
  selectedId: string | null;
  isInspectorOpen: boolean;
  /** The share of the frame a sheet covers from the bottom. */
  covered: number;
  wiring: Wiring | null;
  isDemonstrating: boolean;
  pressed: string | null;
  onAction: (action: BuilderAction) => void;
  onOpen: (id: string, isFromKeyboard: boolean) => void;
  onRemove: (id: string) => void;
};

export function Canvas({
  isLaidOut,
  label,
  subject,
  hintId,
  inspectorId,
  steps,
  graph,
  problems,
  layout,
  orientation,
  selectedId,
  isInspectorOpen,
  covered,
  wiring,
  isDemonstrating,
  pressed,
  onAction,
  onOpen,
  onRemove,
}: CanvasProps) {
  const { frameRef, planeRef, view, isMeasured } = usePanZoom();
  const isReady = isMeasured && isLaidOut;
  const [movingId, setMovingId] = useState<string | null>(null);
  const [isPointerWiring, setIsPointerWiring] = useState(false);
  const gesture = useRef<Gesture | null>(null);
  const hold = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const didDrag = useRef(false);
  const liveRef = useRef<SVGPathElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const isMoving = movingId !== null;
  const held = heldWiringOf(isDemonstrating || isPointerWiring, wiring);
  const demoWiring = heldWiringOf(!isPointerWiring, held);
  const demoPath = demoPathOf(demoWiring, layout, orientation);
  const isPinned = isInspectorOpen && !isMoving;
  const pinnedId = heldIdOf(isPinned, selectedId);
  const pinnedBox = boxOf(layout, pinnedId);

  useLayoutEffect(() => {
    view.setScene(layout.bounds, covered);
  }, [view, layout.bounds, covered]);

  useLayoutEffect(() => {
    view.pin(pinnedBox);
  }, [view, pinnedBox]);

  useLayoutEffect(() => {
    if (isReady) {
      view.settle();
    }
  }, [view, isReady, orientation, covered]);

  useEffect(() => {
    return () => clearTimeout(hold.current);
  }, []);

  useEffect(() => {
    if (!isMoving) {
      return;
    }
    function syncGrid() {
      const grid = gridRef.current;
      if (!grid) {
        return;
      }
      const zoom = view.zoom();
      const origin = view.origin();
      const cell = GRID[orientation];
      grid.style.backgroundSize = `${cell.x * zoom}px ${cell.y * zoom}px`;
      grid.style.backgroundPosition = `${origin.x}px ${origin.y}px`;
    }
    syncGrid();
    return view.subscribe(syncGrid);
  }, [view, isMoving, orientation]);

  function planePointOf(event: React.PointerEvent<HTMLDivElement>) {
    return view.toPlane(clientPointOf(event));
  }

  function aimAt(point: Point, from: string) {
    const id = stepAt(layout.places, point, AIM_REACH);
    if (id === null || !canConnect(graph, from, id)) {
      return null;
    }
    return id;
  }

  /** The wire ends on the pointer, or on the port of the step it would land on. */
  function drawLive(active: Wired, point: Point) {
    const from = layout.places[active.from]?.outputs[active.output];
    if (!from) {
      return;
    }
    const aim = aimAt(point, active.from);
    const end = inputOf(layout, aim) ?? point;
    liveRef.current?.setAttribute('d', wirePathOf(from, end, orientation));
    if (aim !== active.aim) {
      active.aim = aim;
      onAction({ type: 'wireAimed', to: aim });
    }
  }

  function clearLive() {
    liveRef.current?.removeAttribute('d');
  }

  function startWire(
    event: React.PointerEvent<HTMLDivElement>,
    from: string,
    output: OutputId
  ) {
    event.currentTarget.setPointerCapture(event.pointerId);
    const active: Wired = {
      kind: 'wire',
      pointerId: event.pointerId,
      from,
      output,
      aim: null,
    };
    gesture.current = active;
    setIsPointerWiring(true);
    onAction({ type: 'wireStarted', from, output });
    drawLive(active, planePointOf(event));
  }

  function lift(press: Press) {
    clearTimeout(hold.current);
    frameRef.current?.setPointerCapture(press.pointerId);
    gesture.current = { ...press, kind: 'move', cell: press.origin };
    didDrag.current = true;
    setMovingId(press.stepId);
  }

  function liftIfStillPressed(pointerId: number) {
    const active = gesture.current;
    const isSamePress =
      active?.kind === 'press' && active.pointerId === pointerId;
    if (isSamePress) {
      lift(active);
    }
  }

  function startPress(event: React.PointerEvent<HTMLDivElement>, step: Step) {
    const isTouch = event.pointerType === 'touch';
    const pointerId = event.pointerId;
    gesture.current = {
      kind: 'press',
      pointerId,
      stepId: step.id,
      origin: { level: step.level, lane: step.lane },
      startX: event.clientX,
      startY: event.clientY,
      isTouch,
    };
    if (isTouch) {
      hold.current = setTimeout(() => liftIfStillPressed(pointerId), HOLD_MS);
    }
  }

  function startPan(event: React.PointerEvent<HTMLDivElement>) {
    clearTimeout(hold.current);
    event.currentTarget.setPointerCapture(event.pointerId);
    gesture.current = { kind: 'pan' };
    view.grab(event.pointerId, clientPointOf(event));
  }

  /** A second finger turns a pan into a pinch, even when the first one came down on a step. */
  function joinGesture(
    event: React.PointerEvent<HTMLDivElement>,
    active: Gesture
  ) {
    const isTouchPress = active.kind === 'press' && active.isTouch;
    if (isTouchPress) {
      view.grab(active.pointerId, { x: active.startX, y: active.startY });
      event.currentTarget.setPointerCapture(active.pointerId);
      startPan(event);
      return;
    }
    if (active.kind === 'pan') {
      startPan(event);
    }
  }

  /** A press in the menu of a step reaches this handler through React, yet it is not on the canvas. */
  function startGesture(event: React.PointerEvent<HTMLDivElement>) {
    const target = event.target;
    const frame = event.currentTarget;
    const isMainButton = event.button === 0;
    const isOnCanvas = target instanceof Element && frame.contains(target);
    if (!isMainButton || !isOnCanvas) {
      return;
    }
    if (target.closest('[data-canvas-control]')) {
      return;
    }
    engage(frame);
    const active = gesture.current;
    if (active) {
      joinGesture(event, active);
      return;
    }
    didDrag.current = false;
    const card = target.closest<HTMLElement>('[data-step]');
    const step = stepOf(steps, card?.dataset.step ?? null);
    const port = target.closest<HTMLElement>('[data-port]');
    const output = outputOf(port?.dataset.port);
    if (step && output) {
      startWire(event, step.id, output);
      return;
    }
    if (step) {
      startPress(event, step);
      return;
    }
    startPan(event);
  }

  function movePress(event: React.PointerEvent<HTMLDivElement>, press: Press) {
    const dx = event.clientX - press.startX;
    const dy = event.clientY - press.startY;
    const distance = Math.hypot(dx, dy);
    if (distance < slopOf(press.isTouch)) {
      return;
    }
    if (press.isTouch) {
      startPan(event);
      return;
    }
    lift(press);
  }

  function moveStep(event: React.PointerEvent<HTMLDivElement>, move: Moving) {
    const zoom = view.zoom();
    const dx = (event.clientX - move.startX) / zoom;
    const dy = (event.clientY - move.startY) / zoom;
    const cell = draggedCellOf(orientation, move.origin, dx, dy);
    const isSameCell =
      cell.level === move.cell.level && cell.lane === move.cell.lane;
    if (isSameCell) {
      return;
    }
    move.cell = cell;
    onAction({ type: 'moved', id: move.stepId, cell });
  }

  function moveGesture(event: React.PointerEvent<HTMLDivElement>) {
    const active = gesture.current;
    if (!active) {
      return;
    }
    if (active.kind === 'pan') {
      view.drag(event.pointerId, clientPointOf(event));
      return;
    }
    if (event.pointerId !== active.pointerId) {
      return;
    }
    if (active.kind === 'wire') {
      drawLive(active, planePointOf(event));
      return;
    }
    if (active.kind === 'press') {
      movePress(event, active);
      return;
    }
    moveStep(event, active);
  }

  function endWire(action: BuilderAction) {
    clearLive();
    setIsPointerWiring(false);
    onAction(action);
  }

  function finishGesture(
    event: React.PointerEvent<HTMLDivElement>,
    wireAction: BuilderAction
  ) {
    const active = gesture.current;
    if (!active) {
      return;
    }
    if (active.kind === 'pan') {
      view.release(event.pointerId);
      if (!view.isHeld()) {
        gesture.current = null;
      }
      return;
    }
    if (event.pointerId !== active.pointerId) {
      return;
    }
    clearTimeout(hold.current);
    gesture.current = null;
    if (active.kind === 'wire') {
      endWire(wireAction);
      return;
    }
    if (active.kind === 'move') {
      setMovingId(null);
    }
  }

  function endGesture(event: React.PointerEvent<HTMLDivElement>) {
    finishGesture(event, { type: 'wireDropped' });
  }

  function cancelGesture(event: React.PointerEvent<HTMLDivElement>) {
    finishGesture(event, { type: 'wireCancelled' });
  }

  function cancelWire() {
    const active = gesture.current;
    if (active?.kind !== 'wire') {
      return;
    }
    const frame = frameRef.current;
    if (frame?.hasPointerCapture(active.pointerId)) {
      frame.releasePointerCapture(active.pointerId);
    }
    gesture.current = null;
    endWire({ type: 'wireCancelled' });
  }

  function focusStep(id: string) {
    const selector = `[data-step-button="${id}"]`;
    const button = frameRef.current?.querySelector<HTMLElement>(selector);
    button?.focus();
  }

  function handleKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      cancelWire();
      return;
    }
    const target = event.target;
    if (!(target instanceof Element)) {
      return;
    }
    const button = target.closest<HTMLElement>('[data-step-button]');
    const step = stepOf(steps, button?.dataset.stepButton ?? null);
    if (!step) {
      return;
    }
    const isRemoval = event.key === 'Delete' || event.key === 'Backspace';
    if (isRemoval) {
      event.preventDefault();
      onRemove(step.id);
      return;
    }
    if (event.altKey) {
      const origin = { level: step.level, lane: step.lane };
      const cell = nudgedCellOf(orientation, origin, event.key);
      if (cell) {
        event.preventDefault();
        onAction({ type: 'moved', id: step.id, cell });
      }
      return;
    }
    const move = moveOfKey(orientation, event.key);
    if (!move) {
      return;
    }
    event.preventDefault();
    const nextId = neighbourOf(graph, step.id, move);
    if (nextId !== null) {
      onAction({ type: 'selected', id: nextId });
      focusStep(nextId);
    }
  }

  /** The click that ends a move belongs to the move. A click made with a key never does. */
  function openStep(id: string, isFromKeyboard: boolean) {
    const endsMove = didDrag.current && !isFromKeyboard;
    didDrag.current = false;
    if (endsMove) {
      return;
    }
    onOpen(id, isFromKeyboard);
  }

  /** A step that takes the focus from the keyboard is brought into view. A pressed one is already under the pointer. */
  function revealStep(id: string) {
    const box = boxOf(layout, id);
    const isPointerDown = gesture.current !== null;
    if (box && !isPointerDown) {
      view.reveal(box);
    }
  }

  return (
    <>
      <div
        ref={frameRef}
        role='group'
        aria-label={label}
        aria-describedby={hintId}
        data-canvas-frame
        tabIndex={-1}
        onPointerDown={startGesture}
        onPointerMove={moveGesture}
        onPointerUp={endGesture}
        onPointerCancel={cancelGesture}
        onLostPointerCapture={cancelGesture}
        onKeyDown={handleKeys}
        className={FRAME}
      >
        <div
          ref={gridRef}
          aria-hidden='true'
          className={cn(GRID_LINES, gridToneOf(isMoving))}
        />
        <div
          ref={planeRef}
          className={cn(
            'absolute top-0 left-0 origin-top-left',
            !isReady && 'invisible'
          )}
        >
          <WireLayer layout={layout} selectedId={selectedId} />
          {steps.map((step) => {
            const place = layout.places[step.id];
            if (!place) {
              return null;
            }
            const isSelected = step.id === selectedId;
            return (
              <StepCard
                key={step.id}
                step={step}
                place={place}
                graph={graph}
                problems={problemsOfStep(problems, step.id)}
                aim={aimOf(held, graph, step.id)}
                isSelected={isSelected}
                isOpen={isSelected && isInspectorOpen}
                isLifted={step.id === movingId}
                heldOutput={heldOutputOf(step.id, held, pressed)}
                inspectorId={inspectorId}
                onOpen={openStep}
                onReveal={revealStep}
                onAction={onAction}
                onRemove={onRemove}
              />
            );
          })}
          <HeldLayer demoPath={demoPath} liveRef={liveRef} />
        </div>
      </div>
      <ZoomControl view={view} subject={subject} />
    </>
  );
}

'use client';

import {
  EllipsisIcon,
  TrashIcon,
  TriangleAlertIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import {
  choiceOf,
  FIELDS_OF,
  KIND_WORD,
  shownNameOf,
  type OutputId,
  type Step,
} from './data';
import {
  outputLinesOf,
  targetsOf,
  type Graph,
  type OutputLine,
  type Problem,
} from './graph';
import type { Point, StepPlace } from './layout';
import type { BuilderAction } from './session';
import { StepTile } from './step-tile';

/** What a held wire makes of a step: where it leaves, a step it may land on, the one it is over, or one it cannot reach. */
export type Aim = 'idle' | 'source' | 'open' | 'aimed' | 'closed';

const CARD = [
  'bg-card hairline-ring ring-border flex size-full cursor-pointer items-center gap-2.5 rounded-xl p-2.5 text-start',
  'shadow-[0_1px_2px_rgb(0_0_0/0.04)] outline-none transition-[box-shadow,opacity] duration-150 hover:ring-foreground/25',
  'focus-visible:ring-ring focus-visible:ring-offset-background focus-visible:ring-2 focus-visible:ring-offset-2',
].join(' ');

const AIM_CLASS: Record<Aim, string> = {
  idle: '',
  source: '',
  open: 'ring-primary/45 ring-2',
  aimed: 'ring-primary ring-2',
  closed: 'opacity-45',
};

const PORT =
  'group/port absolute top-0 left-0 flex size-6 items-center justify-center';

const DOT =
  'hairline-ring size-2.5 rounded-full transition-[scale,background-color,box-shadow] duration-150 ease-(--ease-out-strong)';

const DOT_FREE = 'bg-card ring-foreground/30';

const DOT_WIRED = 'bg-foreground/45 ring-transparent';

const DOT_OPEN = 'bg-card ring-primary scale-125 ring-2';

const DOT_HELD = 'bg-primary ring-primary scale-150';

const NOTHING = 'nothing';

/** Stripe · Account created: what the step is set to, in one line. */
function detailOf(step: Step) {
  const parts: string[] = [];
  for (const spec of FIELDS_OF[step.kind]) {
    const value = step.values[spec.id] ?? '';
    const label = choiceOf(spec, value)?.label ?? value;
    if (label !== '') {
      parts.push(label);
    }
  }
  return parts.join(' · ');
}

function leadWordOf(line: OutputLine) {
  if (line.target) {
    return `${line.word} leads to ${shownNameOf(line.target)}`;
  }
  if (line.output === 'next') {
    return 'The flow ends here';
  }
  return `${line.word} leads nowhere`;
}

function problemsWordOf(problems: Problem[]) {
  const lines = problems.map((problem) => problem.line);
  if (problems.length === 0) {
    return '';
  }
  if (problems.length === 1) {
    return `1 problem: ${lines[0]}.`;
  }
  return `${problems.length} problems: ${lines.join(', ')}.`;
}

/** The step said in full, since its place and its wires are only drawn. */
function spokenOf(step: Step, lines: OutputLine[], problems: Problem[]) {
  const leads = lines.map(leadWordOf);
  const name = `${KIND_WORD[step.kind]}: ${shownNameOf(step)}.`;
  return `${name} ${leads.join('. ')}. ${problemsWordOf(problems)}`;
}

function connectLabelOf(line: OutputLine) {
  if (line.output === 'next') {
    return 'Connect to';
  }
  return `If ${line.word.toLowerCase()}, connect to`;
}

function inputDotOf(aim: Aim, isReached: boolean) {
  if (aim === 'aimed') {
    return DOT_HELD;
  }
  if (aim === 'open') {
    return DOT_OPEN;
  }
  if (isReached) {
    return DOT_WIRED;
  }
  return DOT_FREE;
}

function outputDotOf(isHeld: boolean, isWired: boolean) {
  if (isHeld) {
    return DOT_HELD;
  }
  if (isWired) {
    return DOT_WIRED;
  }
  return DOT_FREE;
}

/** A port sits on the edge of its card, in a square large enough for a finger. */
function portStyleOf(port: Point, place: StepPlace) {
  const x = port.x - place.box.x - 12;
  const y = port.y - place.box.y - 12;
  return { transform: `translate(${x}px, ${y}px)` };
}

type StepMenuProps = {
  step: Step;
  graph: Graph;
  lines: OutputLine[];
  onAction: (action: BuilderAction) => void;
  onRemove: (id: string) => void;
};

/** Connecting without dragging: every way out of the step, with the steps it may lead to. */
function StepMenu({ step, graph, lines, onAction, onRemove }: StepMenuProps) {
  const targets = targetsOf(graph, step.id);

  function connect(output: OutputId, next: unknown) {
    const target = targets.find((candidate) => candidate.id === next);
    if (target) {
      onAction({ type: 'connected', from: step.id, output, to: target.id });
      return;
    }
    onAction({ type: 'disconnected', from: step.id, output });
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type='button'
            variant='ghost'
            size='icon-sm'
            data-canvas-control
            data-step-menu={step.id}
            aria-label={`Actions for ${shownNameOf(step)}`}
            className='text-muted-foreground absolute top-1 right-1 size-6'
          />
        }
      >
        <EllipsisIcon />
      </DropdownMenuTrigger>
      <DropdownMenuContent align='end' className='min-w-52'>
        {lines.map((line) => (
          <div key={line.output}>
            <DropdownMenuLabel>{connectLabelOf(line)}</DropdownMenuLabel>
            <DropdownMenuRadioGroup
              aria-label={connectLabelOf(line)}
              value={line.target?.id ?? NOTHING}
              onValueChange={(next) => connect(line.output, next)}
            >
              {targets.map((target) => (
                <DropdownMenuRadioItem key={target.id} value={target.id}>
                  {shownNameOf(target)}
                </DropdownMenuRadioItem>
              ))}
              <DropdownMenuRadioItem value={NOTHING}>
                Nothing
              </DropdownMenuRadioItem>
            </DropdownMenuRadioGroup>
          </div>
        ))}
        <DropdownMenuSeparator />
        <DropdownMenuItem
          variant='destructive'
          onClick={() => onRemove(step.id)}
        >
          <TrashIcon />
          Delete step
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export type StepCardProps = {
  step: Step;
  place: StepPlace;
  graph: Graph;
  /** The problems of this step alone. */
  problems: Problem[];
  aim: Aim;
  isSelected: boolean;
  /** The inspector shows this step. */
  isOpen: boolean;
  /** A pointer is moving it along the grid. */
  isLifted: boolean;
  /** The output a wire is held out of, by a pointer or by the demonstration. */
  heldOutput: OutputId | null;
  inspectorId: string;
  onOpen: (id: string, isFromKeyboard: boolean) => void;
  onReveal: (id: string) => void;
  onAction: (action: BuilderAction) => void;
  onRemove: (id: string) => void;
};

export function StepCard({
  step,
  place,
  graph,
  problems,
  aim,
  isSelected,
  isOpen,
  isLifted,
  heldOutput,
  inspectorId,
  onOpen,
  onReveal,
  onAction,
  onRemove,
}: StepCardProps) {
  const lines = outputLinesOf(graph, step);
  const [firstProblem] = problems;
  const isReached = graph.connections.some((link) => link.to === step.id);
  const isRestingSelected = isSelected && aim === 'idle';
  const { box } = place;
  const cardStyle = {
    width: box.width,
    height: box.height,
    transform: `translate(${box.x}px, ${box.y}px)`,
  };

  function open(event: React.MouseEvent<HTMLButtonElement>) {
    const isFromKeyboard = event.detail === 0;
    onOpen(step.id, isFromKeyboard);
  }

  return (
    <div
      data-step={step.id}
      style={cardStyle}
      className={cn(
        'absolute top-0 left-0 transition-transform duration-150 ease-(--ease-out-strong)',
        isLifted && 'z-10'
      )}
    >
      <button
        type='button'
        data-step-button={step.id}
        aria-label={spokenOf(step, lines, problems)}
        aria-expanded={isOpen}
        aria-controls={inspectorId}
        onClick={open}
        onFocus={() => onReveal(step.id)}
        className={cn(
          CARD,
          isRestingSelected && 'ring-primary/60 ring-2',
          isLifted && 'cursor-grabbing shadow-lg shadow-black/10',
          AIM_CLASS[aim]
        )}
      >
        <StepTile step={step} />
        <span className='flex max-h-full min-w-0 flex-1 flex-col overflow-hidden'>
          <span className='text-muted-foreground pe-6 text-[11px] leading-4'>
            {KIND_WORD[step.kind]}
          </span>
          <span className='line-clamp-2 text-[13px] leading-5 font-medium break-words'>
            {shownNameOf(step)}
          </span>
          {firstProblem && (
            <span className='text-warning-foreground flex items-start gap-1 text-xs leading-4'>
              <TriangleAlertIcon className='mt-0.5 size-3 shrink-0' />
              <span className='line-clamp-2'>{firstProblem.line}</span>
            </span>
          )}
          {!firstProblem && (
            <span className='text-muted-foreground line-clamp-2 text-xs leading-4'>
              {detailOf(step)}
            </span>
          )}
        </span>
      </button>
      <StepMenu
        step={step}
        graph={graph}
        lines={lines}
        onAction={onAction}
        onRemove={onRemove}
      />
      {place.input && (
        <span
          aria-hidden='true'
          style={portStyleOf(place.input, place)}
          className={cn(PORT, 'pointer-events-none')}
        >
          <span className={cn(DOT, inputDotOf(aim, isReached))} />
        </span>
      )}
      {lines.map((line) => {
        const port = place.outputs[line.output];
        if (!port) {
          return null;
        }
        const isHeld = heldOutput === line.output;
        const isWired = line.target !== undefined;
        return (
          <span
            key={line.output}
            data-port={line.output}
            aria-hidden='true'
            style={portStyleOf(port, place)}
            className={cn(PORT, 'cursor-crosshair')}
          >
            <span
              className={cn(
                DOT,
                'group-hover/port:ring-primary group-hover/port:scale-125',
                outputDotOf(isHeld, isWired)
              )}
            />
          </span>
        );
      })}
    </div>
  );
}

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { GitBranchIcon, PlugIcon, ZapIcon } from '@/registry/ndeko/lib/icons';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

import { choiceOf, FIELDS_OF, type Step } from './data';

const KIND_PLATE =
  'gem-plate inline-flex size-7 shrink-0 items-center justify-center rounded-md [--gem:var(--primary)] [&_svg]:size-4';

const EMPTY_TILE =
  'keycap-3d text-muted-foreground inline-flex size-7 shrink-0 items-center justify-center rounded-md [&_svg]:size-4';

function appBrandOf(step: Step) {
  const appField = FIELDS_OF.tool.find((spec) => spec.id === 'app');
  if (!appField) {
    return undefined;
  }
  return choiceOf(appField, step.values.app)?.brand;
}

/**
 * What a step wears: a trigger and a condition the plate of their kind, an agent its own picture,
 * a tool the mark of the app it acts in.
 */
export function StepTile({ step }: { step: Step }) {
  if (step.kind === 'trigger') {
    return (
      <span aria-hidden='true' className={KIND_PLATE}>
        <ZapIcon />
      </span>
    );
  }
  if (step.kind === 'condition') {
    return (
      <span aria-hidden='true' className={KIND_PLATE}>
        <GitBranchIcon />
      </span>
    );
  }
  if (step.kind === 'agent') {
    const color = seriesColorOf(step.series ?? 1);
    return <MeshTile seed={step.id} color={color} size='lg' />;
  }
  const brand = appBrandOf(step);
  if (brand) {
    return <BrandTile brand={brand} size='lg' />;
  }
  return (
    <span aria-hidden='true' className={EMPTY_TILE}>
      <PlugIcon />
    </span>
  );
}

'use client';

import { motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

import type { CanvasLayout, PlacedWire } from './layout';
import type { Wire } from './session';

const LAYER =
  'pointer-events-none absolute top-0 left-0 size-px overflow-visible';

/** Where the browser can ease a path, a wire follows its step when the step moves along the grid. */
const WIRE =
  'fill-none stroke-[1.5px] transition-[d,stroke] duration-[150ms,300ms] ease-(--ease-out-strong) [stroke-linecap:round]';

/** A wire that has just been made shows in the brand colour, then settles among the others. */
const LANDED = 'starting:stroke-primary';

const HELD = 'fill-none stroke-primary stroke-2 [stroke-linecap:round]';

const DRAW = { duration: 0.5, ease: EASE_OUT_STRONG };

const REACH = { duration: 0.45, ease: EASE_OUT_STRONG };

function toneOf(isLit: boolean) {
  if (isLit) {
    return 'stroke-primary/70';
  }
  return 'stroke-foreground/30';
}

function drawStartOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return { pathLength: 1 };
  }
  return { pathLength: 0 };
}

function touchesStep(wire: Wire, stepId: string | null) {
  return wire.from === stepId || wire.to === stepId;
}

type WirePathProps = {
  wire: PlacedWire<Wire>;
  isLit: boolean;
};

/** Only a wire made from a menu draws itself: one let go by a hand is already where it lands. */
function WirePath({ wire, isLit }: WirePathProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const tone = toneOf(isLit);

  if (wire.link.arrival === 'drawn') {
    return (
      <motion.path
        d={wire.path}
        initial={drawStartOf(shouldReduceMotion)}
        animate={{ pathLength: 1 }}
        transition={DRAW}
        className={cn(WIRE, LANDED, tone)}
      />
    );
  }

  const hasLanded = wire.link.arrival === 'dropped';

  return <path d={wire.path} className={cn(WIRE, hasLanded && LANDED, tone)} />;
}

type WireLayerProps = {
  layout: CanvasLayout<Wire>;
  selectedId: string | null;
};

export function WireLayer({ layout, selectedId }: WireLayerProps) {
  return (
    <svg aria-hidden='true' className={LAYER}>
      {layout.wires.map((wire) => (
        <WirePath
          key={`${wire.id}:${wire.link.to}`}
          wire={wire}
          isLit={touchesStep(wire.link, selectedId)}
        />
      ))}
      {layout.labels.map((label) => (
        <text
          key={label.id}
          x={label.x}
          y={label.y}
          className='fill-muted-foreground text-[10px] font-medium'
        >
          {label.text}
        </text>
      ))}
    </svg>
  );
}

type HeldLayerProps = {
  /** The wire the demonstration holds out, from its port to the step it aims at. */
  demoPath: string | null;
  /** The wire a pointer holds. Its path is written to the element on every move, never rendered. */
  liveRef: React.Ref<SVGPathElement>;
};

export function HeldLayer({ demoPath, liveRef }: HeldLayerProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <svg aria-hidden='true' className={LAYER}>
      {demoPath && (
        <motion.path
          key={demoPath}
          d={demoPath}
          initial={drawStartOf(shouldReduceMotion)}
          animate={{ pathLength: 1 }}
          transition={REACH}
          className={HELD}
        />
      )}
      <path ref={liveRef} className={HELD} />
    </svg>
  );
}

