import {
  MAX_ZOOM,
  MIN_ZOOM,
  useZoomPercent,
  type CanvasView,
} from './use-pan-zoom';

const ZOOM_STEP = 1.25;

const MIN_PERCENT = Math.round(MIN_ZOOM * 100);

const MAX_PERCENT = Math.round(MAX_ZOOM * 100);

type ZoomControlProps = {
  view: CanvasView;
  /** What Fit brings into view, for its accessible name. */
  subject: string;
};

/** It sits on the canvas and is the only part that renders again while the zoom changes. */
export function ZoomControl({ view, subject }: ZoomControlProps) {
  const percent = useZoomPercent(view);
  const isSmallest = percent <= MIN_PERCENT;
  const isLargest = percent >= MAX_PERCENT;

  return (
    <div
      role='group'
      aria-label='Zoom'
      className='bg-card hairline-ring ring-border absolute bottom-3 left-3 flex items-center gap-0.5 rounded-full p-0.5 shadow-[0_1px_2px_rgb(0_0_0/0.05)]'
    >
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        aria-label='Zoom out'
        disabled={isSmallest}
        focusableWhenDisabled
        onClick={() => view.zoomStep(1 / ZOOM_STEP)}
        className='rounded-full'
      >
        <MinusIcon />
      </Button>
      <Button
        type='button'
        variant='ghost'
        size='sm'
        aria-label={`Zoom ${percent}%. Reset to 100%`}
        onClick={() => view.zoomTo(1)}
        className='w-12 rounded-full px-0 tabular-nums'
      >
        {percent}%
      </Button>
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        aria-label='Zoom in'
        disabled={isLargest}
        focusableWhenDisabled
        onClick={() => view.zoomStep(ZOOM_STEP)}
        className='rounded-full'
      >
        <PlusIcon />
      </Button>
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        aria-label={`Fit ${subject} in view`}
        onClick={() => view.fit()}
        className='rounded-full'
      >
        <MaximizeIcon />
      </Button>
    </div>
  );
}

'use client';

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from 'react';

type Point = {
  x: number;
  y: number;
};

type Box = Point & {
  width: number;
  height: number;
};

type Viewport = Point & {
  zoom: number;
};

type Span = {
  centre: Point;
  distance: number;
};

export const MIN_ZOOM = 0.4;

export const MAX_ZOOM = 1.6;

/** Fit never enlarges past full size: a small flow stays readable instead of filling the frame. */
const FIT_MAX_ZOOM = 1;

/** Nor does it shrink a flow until its text cannot be read: what does not fit is reached by panning. */
const FIT_MIN_ZOOM = 0.75;

const FIT_MARGIN = 20;

const REVEAL_MARGIN = 16;

const EASED = 'transform 220ms cubic-bezier(0.23, 1, 0.32, 1)';

/** A wheel that reports lines, as some mice do, moves this many pixels a line. */
const LINE_PIXELS = 16;

const WHEEL_DOM_DELTA_LINE = 1;

const WHEEL_ZOOM_RATE = 0.01;

/** One wheel event never zooms by more than about a quarter. */
const WHEEL_ZOOM_LIMIT = 24;

const NO_BOX: Box = { x: 0, y: 0, width: 1, height: 1 };

function clamp(value: number, min: number, max: number) {
  const atLeast = Math.max(value, min);
  return Math.min(atLeast, max);
}

function transitionOf(isEased: boolean) {
  if (isEased) {
    return EASED;
  }
  return 'none';
}

/** How far a span has to move to sit between two edges. Its start wins when it is too long to fit. */
function shiftOf(start: number, end: number, min: number, max: number) {
  if (start < min) {
    return min - start;
  }
  if (end > max) {
    const back = max - end;
    const untilStart = min - start;
    return Math.max(back, untilStart);
  }
  return 0;
}

/**
 * Where the content starts along one axis of the frame: centred when it fits, at the margin when it
 * does not, so the start of the flow is what shows.
 */
function startOf(
  frameSize: number,
  contentStart: number,
  contentSize: number,
  zoom: number
) {
  const scaled = contentSize * zoom;
  const room = frameSize - FIT_MARGIN * 2;
  if (scaled <= room) {
    return (frameSize - scaled) / 2 - contentStart * zoom;
  }
  return FIT_MARGIN - contentStart * zoom;
}

function spanOf(pointers: Map<number, Point>): Span | null {
  const [first, second] = Array.from(pointers.values());
  if (!first || !second) {
    return null;
  }
  const centre = { x: (first.x + second.x) / 2, y: (first.y + second.y) / 2 };
  const distance = Math.hypot(second.x - first.x, second.y - first.y);
  return { centre, distance };
}

function wheelUnitOf(event: WheelEvent) {
  if (event.deltaMode === WHEEL_DOM_DELTA_LINE) {
    return LINE_PIXELS;
  }
  return 1;
}

/** Ctrl or Cmd with the wheel, which is also how a trackpad reports a pinch. */
function isZoomWheel(event: WheelEvent) {
  return event.ctrlKey || event.metaKey;
}

/**
 * Pan and zoom of a canvas as one transform on one plane element. The transform is written to the
 * element, never through React state: a drag or a pinch changes it on every frame.
 */
export function createCanvasView() {
  let frame: HTMLElement | null = null;
  let plane: HTMLElement | null = null;
  let viewport: Viewport = { x: 0, y: 0, zoom: 1 };
  let content = NO_BOX;
  let coveredShare = 0;
  let pinned: Box | null = null;
  /** True once a person has moved the view: it is no longer refitted when the frame changes size. */
  let isManual = false;
  let hasFitted = false;
  const listeners = new Set<() => void>();
  const pointers = new Map<number, Point>();

  function sizeOf() {
    if (!frame) {
      return null;
    }
    return { width: frame.clientWidth, height: frame.clientHeight };
  }

  function apply(next: Viewport, isEased: boolean) {
    const x = Math.round(next.x);
    const y = Math.round(next.y);
    viewport = { x, y, zoom: next.zoom };
    if (plane) {
      plane.style.transition = transitionOf(isEased);
      plane.style.transform = `translate(${x}px, ${y}px) scale(${next.zoom})`;
    }
    listeners.forEach((listener) => listener());
  }

  function localOf(client: Point): Point {
    const rect = frame?.getBoundingClientRect();
    if (!rect) {
      return client;
    }
    return { x: client.x - rect.left, y: client.y - rect.top };
  }

  function centreOf(): Point {
    const size = sizeOf();
    if (!size) {
      return { x: 0, y: 0 };
    }
    return { x: size.width / 2, y: size.height / 2 };
  }

  /** The point under `anchor` stays under it while the zoom changes. */
  function zoomedAround(factor: number, anchor: Point): Viewport {
    const zoom = clamp(viewport.zoom * factor, MIN_ZOOM, MAX_ZOOM);
    const ratio = zoom / viewport.zoom;
    const x = anchor.x - (anchor.x - viewport.x) * ratio;
    const y = anchor.y - (anchor.y - viewport.y) * ratio;
    return { x, y, zoom };
  }

  function fitted(): Viewport | null {
    const size = sizeOf();
    if (!size) {
      return null;
    }
    const roomX = size.width - FIT_MARGIN * 2;
    const roomY = size.height - FIT_MARGIN * 2;
    const scale = Math.min(roomX / content.width, roomY / content.height);
    const zoom = clamp(scale, FIT_MIN_ZOOM, FIT_MAX_ZOOM);
    const x = startOf(size.width, content.x, content.width, zoom);
    const y = startOf(size.height, content.y, content.height, zoom);
    return { x, y, zoom };
  }

  function revealed(box: Box): Viewport | null {
    const size = sizeOf();
    if (!size) {
      return null;
    }
    const left = box.x * viewport.zoom + viewport.x;
    const top = box.y * viewport.zoom + viewport.y;
    const right = left + box.width * viewport.zoom;
    const bottom = top + box.height * viewport.zoom;
    const visibleHeight = size.height * (1 - coveredShare);
    const maxX = size.width - REVEAL_MARGIN;
    const maxY = visibleHeight - REVEAL_MARGIN;
    const dx = shiftOf(left, right, REVEAL_MARGIN, maxX);
    const dy = shiftOf(top, bottom, REVEAL_MARGIN, maxY);
    if (dx === 0 && dy === 0) {
      return null;
    }
    return { ...viewport, x: viewport.x + dx, y: viewport.y + dy };
  }

  function refit(isEased: boolean) {
    const next = fitted();
    if (next) {
      hasFitted = true;
      apply(next, isEased);
    }
  }

  /**
   * Focus on a step outside the frame makes the browser scroll the frame to it. The scroll is taken
   * back and given to the transform, so the plane stays the only thing that moves.
   */
  function absorbScroll() {
    if (!frame) {
      return;
    }
    const left = frame.scrollLeft;
    const top = frame.scrollTop;
    if (left === 0 && top === 0) {
      return;
    }
    frame.scrollLeft = 0;
    frame.scrollTop = 0;
    apply({ ...viewport, x: viewport.x - left, y: viewport.y - top }, false);
  }

  function reveal(box: Box) {
    absorbScroll();
    if (!hasFitted) {
      return;
    }
    const next = revealed(box);
    if (next) {
      apply(next, true);
    }
  }

  function panBy(dx: number, dy: number) {
    isManual = true;
    apply({ ...viewport, x: viewport.x + dx, y: viewport.y + dy }, false);
  }

  function pinch(before: Span, after: Span) {
    if (before.distance === 0) {
      return;
    }
    const factor = after.distance / before.distance;
    const zoomed = zoomedAround(factor, localOf(before.centre));
    const x = zoomed.x + after.centre.x - before.centre.x;
    const y = zoomed.y + after.centre.y - before.centre.y;
    isManual = true;
    apply({ x, y, zoom: zoomed.zoom }, false);
  }

  return {
    /** The frame that clips the canvas and the plane that moves inside it. */
    attach(nextFrame: HTMLElement | null, nextPlane: HTMLElement | null) {
      frame = nextFrame;
      plane = nextPlane;
    },
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    percent() {
      return Math.round(viewport.zoom * 100);
    },
    zoom() {
      return viewport.zoom;
    },
    origin(): Point {
      return { x: viewport.x, y: viewport.y };
    },
    /** A point of the screen as a point of the plane. */
    toPlane(client: Point): Point {
      const local = localOf(client);
      const x = (local.x - viewport.x) / viewport.zoom;
      const y = (local.y - viewport.y) / viewport.zoom;
      return { x, y };
    },
    panBy,
    zoomStep(factor: number) {
      isManual = true;
      apply(zoomedAround(factor, centreOf()), true);
    },
    zoomTo(zoom: number) {
      isManual = true;
      apply(zoomedAround(zoom / viewport.zoom, centreOf()), true);
    },
    /** Shows everything again and hands the view back to the canvas, which refits it on its own. */
    fit() {
      isManual = false;
      refit(true);
    },
    /** What Fit shows, and the share of the frame a sheet covers from the bottom, from 0 to 1. */
    setScene(bounds: Box, covered: number) {
      content = bounds;
      coveredShare = covered;
    },
    /** Called when the frame, the layout or the sheet changed: refits a view nobody moved. */
    settle() {
      const isFirst = !hasFitted;
      if (isFirst || !isManual) {
        refit(!isFirst);
      }
      if (!pinned) {
        return;
      }
      const next = revealed(pinned);
      if (next) {
        apply(next, !isFirst);
      }
    },
    reveal,
    /** The box to keep in view, now and whenever the frame changes size. */
    pin(box: Box | null) {
      pinned = box;
      if (box) {
        reveal(box);
      }
    },
    absorbScroll,
    grab(pointerId: number, at: Point) {
      pointers.set(pointerId, at);
    },
    /** One pointer pans. Two pointers pinch: the zoom follows their distance, the pan their middle. */
    drag(pointerId: number, now: Point) {
      const last = pointers.get(pointerId);
      if (!last) {
        return;
      }
      const before = spanOf(pointers);
      pointers.set(pointerId, now);
      const after = spanOf(pointers);
      if (before && after) {
        pinch(before, after);
        return;
      }
      panBy(now.x - last.x, now.y - last.y);
    },
    release(pointerId: number) {
      pointers.delete(pointerId);
    },
    isHeld() {
      return pointers.size > 0;
    },
    /** A plain wheel pans. A zoom wheel zooms around the pointer. */
    takeWheel(event: WheelEvent) {
      const unit = wheelUnitOf(event);
      if (!isZoomWheel(event)) {
        panBy(-event.deltaX * unit, -event.deltaY * unit);
        return;
      }
      const raw = event.deltaY * unit;
      const delta = clamp(raw, -WHEEL_ZOOM_LIMIT, WHEEL_ZOOM_LIMIT);
      const factor = Math.exp(-delta * WHEEL_ZOOM_RATE);
      const anchor = localOf({ x: event.clientX, y: event.clientY });
      isManual = true;
      apply(zoomedAround(factor, anchor), false);
    },
  };
}

export type CanvasView = ReturnType<typeof createCanvasView>;

/**
 * The frame and the plane of a canvas, with its view. Call it in the component that renders them,
 * before any effect that uses the view. A plain wheel pans only while the focus is inside the
 * parent of the frame, so a page scrolled past the canvas keeps scrolling. A pinch always zooms the
 * canvas under it, never the page.
 */
export function usePanZoom() {
  const frameRef = useRef<HTMLDivElement>(null);
  const planeRef = useRef<HTMLDivElement>(null);
  const [view] = useState(createCanvasView);
  const [isMeasured, setIsMeasured] = useState(false);

  useLayoutEffect(() => {
    view.attach(frameRef.current, planeRef.current);
    return () => view.attach(null, null);
  }, [view]);

  useEffect(() => {
    const frame = frameRef.current;
    if (!frame) {
      return;
    }
    const scope = frame.parentElement ?? frame;
    let hasMeasured = false;

    /** The first fit is left to the canvas, which knows by then what it shows. */
    function measure() {
      setIsMeasured(true);
      if (hasMeasured) {
        view.settle();
      }
      hasMeasured = true;
    }

    function takeWheel(event: WheelEvent) {
      const isEngaged = scope.matches(':focus-within');
      const isZoom = isZoomWheel(event);
      if (!isEngaged && !isZoom) {
        return;
      }
      event.preventDefault();
      view.takeWheel(event);
    }

    const observer = new ResizeObserver(measure);
    observer.observe(frame);
    frame.addEventListener('wheel', takeWheel, { passive: false });
    frame.addEventListener('scroll', view.absorbScroll);
    return () => {
      observer.disconnect();
      frame.removeEventListener('wheel', takeWheel);
      frame.removeEventListener('scroll', view.absorbScroll);
    };
  }, [view]);

  return { frameRef, planeRef, view, isMeasured };
}

function fullSize() {
  return 100;
}

/** The zoom as a whole percentage. Only the text that shows it renders again when it changes. */
export function useZoomPercent(view: CanvasView) {
  return useSyncExternalStore(view.subscribe, view.percent, fullSize);
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * How wide the builder itself is, whatever the window: a phone gets the flow from top to bottom and
 * the inspector as a sheet, a compact width keeps the flow from top to bottom beside the inspector,
 * a wide one lays the flow from left to right.
 */
export type WidthBand = 'phone' | 'compact' | 'wide';

const PHONE_BELOW = 640;

const WIDE_FROM = 1100;

function bandOf(width: number): WidthBand {
  if (width < PHONE_BELOW) {
    return 'phone';
  }
  if (width < WIDE_FROM) {
    return 'compact';
  }
  return 'wide';
}

/** Null until the element has been measured, so nothing is laid out for the wrong width first. */
export function useWidthBand(ref: RefObject<HTMLElement | null>) {
  const [band, setBand] = useState<WidthBand | null>(null);

  useEffect(() => {
    const element = ref.current;
    if (!element) {
      return;
    }
    const observer = new ResizeObserver(([entry]) => {
      setBand(bandOf(entry.contentRect.width));
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, [ref]);

  return band;
}

import {
  OUTPUT_WORD,
  OUTPUTS_OF,
  type Connection,
  type OutputId,
  type Step,
} from './data';
import type { Move } from './graph';

/** A wide canvas reads from left to right. A narrow one, such as a phone, reads from top to bottom. */
export type Orientation = 'across' | 'down';

export type Point = {
  x: number;
  y: number;
};

export type Box = Point & {
  width: number;
  height: number;
};

export type Cell = {
  level: number;
  lane: number;
};

/** A wide canvas has room for a whole name on one line. On a narrow one the name wraps to a second line. */
const CARD_WIDTH: Record<Orientation, number> = {
  across: 240,
  down: 192,
};

/** Tall enough for the kind, a name on two lines and one line of detail. */
const CARD_HEIGHT = 92;

/** The pixels of one grid unit along the flow and across it. A step is twelve units from the next one. */
const PITCH: Record<Orientation, Cell> = {
  across: { level: 24, lane: 24 },
  down: { level: 12, lane: 36 },
};

/** The grid drawn while a step is dragged: the lines a step snaps to. */
export const GRID: Record<Orientation, Point> = {
  across: { x: 24, y: 24 },
  down: { x: 36, y: 24 },
};

const LEVEL_MIN = -20;

const LEVEL_MAX = 60;

const LANE_MIN = -10;

const LANE_MAX = 20;

/** How far a wire runs straight out of a port before it turns. */
const MIN_REACH = 36;

export type StepPlace = {
  box: Box;
  /** Where wires arrive. A trigger starts the flow and has none. */
  input: Point | null;
  outputs: Partial<Record<OutputId, Point>>;
};

export type PlacedWire<Link extends Connection> = {
  id: string;
  link: Link;
  path: string;
};

export type OutputLabel = {
  id: string;
  text: string;
  x: number;
  y: number;
};

export type CanvasLayout<Link extends Connection> = {
  places: Record<string, StepPlace>;
  wires: PlacedWire<Link>[];
  /** Yes and No, written where each leaves a condition. */
  labels: OutputLabel[];
  bounds: Box;
};

function clamp(value: number, min: number, max: number) {
  const atLeast = Math.max(value, min);
  return Math.min(atLeast, max);
}

function originOf(step: Step, orientation: Orientation): Point {
  const pitch = PITCH[orientation];
  const along = step.level * pitch.level;
  const across = step.lane * pitch.lane;
  if (orientation === 'across') {
    return { x: along, y: across };
  }
  return { x: across, y: along };
}

function inputPointOf(box: Box, orientation: Orientation): Point {
  if (orientation === 'across') {
    return { x: box.x, y: box.y + box.height / 2 };
  }
  return { x: box.x + box.width / 2, y: box.y };
}

/** One output leaves from the middle of the edge, two from its thirds. */
function outputPointOf(
  box: Box,
  index: number,
  count: number,
  orientation: Orientation
): Point {
  const share = (index + 1) / (count + 1);
  if (orientation === 'across') {
    return { x: box.x + box.width, y: box.y + box.height * share };
  }
  return { x: box.x + box.width * share, y: box.y + box.height };
}

function placeOf(step: Step, orientation: Orientation): StepPlace {
  const origin = originOf(step, orientation);
  const width = CARD_WIDTH[orientation];
  const box = { ...origin, width, height: CARD_HEIGHT };
  const outputIds = OUTPUTS_OF[step.kind];
  const outputs: Partial<Record<OutputId, Point>> = {};
  outputIds.forEach((output, index) => {
    outputs[output] = outputPointOf(box, index, outputIds.length, orientation);
  });
  if (step.kind === 'trigger') {
    return { box, input: null, outputs };
  }
  return { box, input: inputPointOf(box, orientation), outputs };
}

export function wirePathOf(from: Point, to: Point, orientation: Orientation) {
  if (orientation === 'across') {
    const span = Math.abs(to.x - from.x);
    const reach = Math.max(MIN_REACH, span / 2);
    const leaveX = from.x + reach;
    const arriveX = to.x - reach;
    return `M ${from.x} ${from.y} C ${leaveX} ${from.y}, ${arriveX} ${to.y}, ${to.x} ${to.y}`;
  }
  const span = Math.abs(to.y - from.y);
  const reach = Math.max(MIN_REACH, span / 2);
  const leaveY = from.y + reach;
  const arriveY = to.y - reach;
  return `M ${from.x} ${from.y} C ${from.x} ${leaveY}, ${to.x} ${arriveY}, ${to.x} ${to.y}`;
}

export function wireIdOf(link: Connection) {
  return `${link.from}:${link.output}`;
}

function labelOf(
  step: Step,
  output: OutputId,
  port: Point,
  orientation: Orientation
): OutputLabel {
  const id = `${step.id}:${output}`;
  const text = OUTPUT_WORD[output];
  if (orientation === 'across') {
    return { id, text, x: port.x + 10, y: port.y - 6 };
  }
  return { id, text, x: port.x + 9, y: port.y + 14 };
}

function labelsOf(
  steps: Step[],
  places: Record<string, StepPlace>,
  orientation: Orientation
) {
  const labels: OutputLabel[] = [];
  const forks = steps.filter((step) => step.kind === 'condition');
  for (const step of forks) {
    for (const output of OUTPUTS_OF.condition) {
      const port = places[step.id]?.outputs[output];
      if (port) {
        labels.push(labelOf(step, output, port, orientation));
      }
    }
  }
  return labels;
}

function boundsOf(places: StepPlace[], orientation: Orientation): Box {
  if (places.length === 0) {
    const width = CARD_WIDTH[orientation];
    return { x: 0, y: 0, width, height: CARD_HEIGHT };
  }
  const lefts = places.map((place) => place.box.x);
  const tops = places.map((place) => place.box.y);
  const rights = places.map((place) => place.box.x + place.box.width);
  const bottoms = places.map((place) => place.box.y + place.box.height);
  const x = Math.min(...lefts);
  const y = Math.min(...tops);
  return {
    x,
    y,
    width: Math.max(...rights) - x,
    height: Math.max(...bottoms) - y,
  };
}

/** Everything the canvas draws, worked out from the steps and their connections alone. */
export function layoutOf<Link extends Connection>(
  steps: Step[],
  connections: Link[],
  orientation: Orientation
): CanvasLayout<Link> {
  const places: Record<string, StepPlace> = {};
  for (const step of steps) {
    places[step.id] = placeOf(step, orientation);
  }
  const wires: PlacedWire<Link>[] = [];
  for (const link of connections) {
    const from = places[link.from]?.outputs[link.output];
    const to = places[link.to]?.input;
    if (from && to) {
      wires.push({
        id: wireIdOf(link),
        link,
        path: wirePathOf(from, to, orientation),
      });
    }
  }
  return {
    places,
    wires,
    labels: labelsOf(steps, places, orientation),
    bounds: boundsOf(Object.values(places), orientation),
  };
}

/** The pixels between two drawn lines, along the flow and across it. */
function lineGapOf(orientation: Orientation): Cell {
  const grid = GRID[orientation];
  if (orientation === 'across') {
    return { level: grid.x, lane: grid.y };
  }
  return { level: grid.y, lane: grid.x };
}

/** A whole number of drawn lines, in grid units: on a phone a line is two units apart along the flow. */
function snappedUnitsOf(pixels: number, lineGap: number, unit: number) {
  const lines = Math.round(pixels / lineGap);
  const unitsPerLine = Math.round(lineGap / unit);
  return lines * unitsPerLine;
}

/** The cell a step dragged by `dx` and `dy` pixels of the canvas snaps to: always on a drawn line. */
export function draggedCellOf(
  orientation: Orientation,
  origin: Cell,
  dx: number,
  dy: number
): Cell {
  const pitch = PITCH[orientation];
  const lineGap = lineGapOf(orientation);
  let along = dx;
  let across = dy;
  if (orientation === 'down') {
    along = dy;
    across = dx;
  }
  const levelShift = snappedUnitsOf(along, lineGap.level, pitch.level);
  const laneShift = snappedUnitsOf(across, lineGap.lane, pitch.lane);
  const level = origin.level + levelShift;
  const lane = origin.lane + laneShift;
  return {
    level: clamp(level, LEVEL_MIN, LEVEL_MAX),
    lane: clamp(lane, LANE_MIN, LANE_MAX),
  };
}

const DIRECTIONS: Partial<Record<string, Point>> = {
  ArrowLeft: { x: -1, y: 0 },
  ArrowRight: { x: 1, y: 0 },
  ArrowUp: { x: 0, y: -1 },
  ArrowDown: { x: 0, y: 1 },
};

/** One line of the grid in the direction of an arrow key, or null for any other key. */
export function nudgedCellOf(
  orientation: Orientation,
  origin: Cell,
  key: string
) {
  const direction = DIRECTIONS[key];
  if (!direction) {
    return null;
  }
  const grid = GRID[orientation];
  const dx = direction.x * grid.x;
  const dy = direction.y * grid.y;
  return draggedCellOf(orientation, origin, dx, dy);
}

const MOVES: Record<Orientation, Partial<Record<string, Move>>> = {
  across: {
    ArrowRight: 'forward',
    ArrowLeft: 'back',
    ArrowDown: 'next',
    ArrowUp: 'previous',
  },
  down: {
    ArrowDown: 'forward',
    ArrowUp: 'back',
    ArrowRight: 'next',
    ArrowLeft: 'previous',
  },
};

/** An arrow key follows the flow in the direction the canvas reads. */
export function moveOfKey(orientation: Orientation, key: string) {
  return MOVES[orientation][key] ?? null;
}

function contains(box: Box, point: Point, reach: number) {
  const isInsideX =
    point.x >= box.x - reach && point.x <= box.x + box.width + reach;
  const isInsideY =
    point.y >= box.y - reach && point.y <= box.y + box.height + reach;
  return isInsideX && isInsideY;
}

/** The step under a point of the canvas, with some reach around its card so a wire lands easily. */
export function stepAt(
  places: Record<string, StepPlace>,
  point: Point,
  reach: number
) {
  const ids = Object.keys(places);
  const found = ids.find((id) => contains(places[id].box, point, reach));
  return found ?? null;
}

import {
  FIELDS_OF,
  OUTPUT_WORD,
  OUTPUTS_OF,
  type Connection,
  type FieldId,
  type OutputId,
  type Step,
} from './data';

export type Graph = {
  steps: Step[];
  connections: Connection[];
};

export function stepOf(steps: Step[], id: string | null) {
  if (id === null) {
    return undefined;
  }
  return steps.find((step) => step.id === id);
}

export function targetOf(
  connections: Connection[],
  from: string,
  output: OutputId
) {
  const link = connections.find(
    (candidate) => candidate.from === from && candidate.output === output
  );
  return link?.to ?? null;
}

function leadsTo(connections: Connection[], start: string, goal: string) {
  const seen = new Set<string>();
  const pending = [start];
  let current = pending.pop();
  while (current !== undefined) {
    if (current === goal) {
      return true;
    }
    if (!seen.has(current)) {
      seen.add(current);
      const reached = current;
      const links = connections.filter((link) => link.from === reached);
      links.forEach((link) => pending.push(link.to));
    }
    current = pending.pop();
  }
  return false;
}

export type Refusal = 'missing' | 'self' | 'start' | 'loop';

/** Why a wire cannot go from one step to another, or null when it can. */
export function refusalOf(
  graph: Graph,
  from: string,
  to: string
): Refusal | null {
  const source = stepOf(graph.steps, from);
  const target = stepOf(graph.steps, to);
  if (!source || !target) {
    return 'missing';
  }
  if (from === to) {
    return 'self';
  }
  if (target.kind === 'trigger') {
    return 'start';
  }
  if (leadsTo(graph.connections, to, from)) {
    return 'loop';
  }
  return null;
}

export function canConnect(graph: Graph, from: string, to: string) {
  return refusalOf(graph, from, to) === null;
}

/** The steps a wire from `from` may land on. */
export function targetsOf(graph: Graph, from: string) {
  return graph.steps.filter((step) => canConnect(graph, from, step.id));
}

export type ProblemField = FieldId | 'name';

export type Problem = {
  stepId: string;
  line: string;
  /** The field to fill, when the problem is a missing value. */
  field?: ProblemField;
};

function isBlank(value: string | undefined) {
  const text = value ?? '';
  return text.trim() === '';
}

function fieldProblemsOf(step: Step): Problem[] {
  const problems: Problem[] = [];
  if (isBlank(step.name)) {
    problems.push({ stepId: step.id, line: 'Name the step', field: 'name' });
  }
  for (const spec of FIELDS_OF[step.kind]) {
    if (isBlank(step.values[spec.id])) {
      problems.push({
        stepId: step.id,
        line: spec.missingLine,
        field: spec.id,
      });
    }
  }
  return problems;
}

function inputProblemsOf(graph: Graph, step: Step): Problem[] {
  if (step.kind === 'trigger') {
    return [];
  }
  const isReached = graph.connections.some((link) => link.to === step.id);
  if (isReached) {
    return [];
  }
  return [{ stepId: step.id, line: 'Nothing leads to this step' }];
}

/** Both answers of a condition have to go somewhere. Any other step may end the flow. */
function outputProblemsOf(graph: Graph, step: Step): Problem[] {
  if (step.kind !== 'condition') {
    return [];
  }
  const open = OUTPUTS_OF.condition.filter(
    (output) => targetOf(graph.connections, step.id, output) === null
  );
  return open.map((output) => ({
    stepId: step.id,
    line: `${OUTPUT_WORD[output]} leads nowhere`,
  }));
}

export function problemsOf(graph: Graph) {
  const problems: Problem[] = [];
  for (const step of graph.steps) {
    problems.push(...fieldProblemsOf(step));
    problems.push(...inputProblemsOf(graph, step));
    problems.push(...outputProblemsOf(graph, step));
  }
  return problems;
}

export function problemsOfStep(problems: Problem[], stepId: string) {
  return problems.filter((problem) => problem.stepId === stepId);
}

export type OutputLine = {
  output: OutputId;
  word: string;
  target: Step | undefined;
};

/** Where each way out of a step leads, for the inspector and for screen readers. */
export function outputLinesOf(graph: Graph, step: Step): OutputLine[] {
  return OUTPUTS_OF[step.kind].map((output) => {
    const targetId = targetOf(graph.connections, step.id, output);
    return {
      output,
      word: OUTPUT_WORD[output],
      target: stepOf(graph.steps, targetId),
    };
  });
}

export type Move = 'forward' | 'back' | 'next' | 'previous';

function forwardOf(graph: Graph, id: string) {
  const step = stepOf(graph.steps, id);
  if (!step) {
    return null;
  }
  for (const output of OUTPUTS_OF[step.kind]) {
    const target = targetOf(graph.connections, id, output);
    if (target !== null) {
      return target;
    }
  }
  return null;
}

function backOf(graph: Graph, id: string) {
  const link = graph.connections.find((candidate) => candidate.to === id);
  return link?.from ?? null;
}

/** The steps a fork leads to, in the order of its outputs. */
function siblingsOf(graph: Graph, id: string) {
  const sourceId = backOf(graph, id);
  const source = stepOf(graph.steps, sourceId);
  if (!source) {
    return [];
  }
  const siblings: string[] = [];
  for (const output of OUTPUTS_OF[source.kind]) {
    const target = targetOf(graph.connections, source.id, output);
    if (target !== null && !siblings.includes(target)) {
      siblings.push(target);
    }
  }
  return siblings;
}

function siblingOf(graph: Graph, id: string, offset: number) {
  const siblings = siblingsOf(graph, id);
  const index = siblings.indexOf(id);
  if (index === -1) {
    return null;
  }
  return siblings[index + offset] ?? null;
}

/** The step an arrow key moves to: along a connection, or to the other branch of a fork. */
export function neighbourOf(graph: Graph, id: string, move: Move) {
  if (move === 'forward') {
    return forwardOf(graph, id);
  }
  if (move === 'back') {
    return backOf(graph, id);
  }
  if (move === 'next') {
    return siblingOf(graph, id, 1);
  }
  return siblingOf(graph, id, -1);
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import {
  CONNECTIONS,
  DEMO_INSTRUCTIONS,
  OUTPUT_WORD,
  OUTPUTS_OF,
  shownNameOf,
  STEPS,
  type Connection,
  type FieldId,
  type OutputId,
  type Step,
} from './data';
import {
  canConnect,
  problemsOf,
  stepOf,
  targetOf,
  type Graph,
  type Problem,
} from './graph';
import type { Cell } from './layout';

/**
 * How a wire came to be: there from the start, let go by a hand where it now sits, or made from a
 * menu. Only the last one draws itself, since the two others are already where they belong.
 */
export type Arrival = 'placed' | 'dropped' | 'drawn';

export type Wire = Connection & {
  arrival: Arrival;
};

/** A wire held out of a port: by a pointer, or by the demonstration. `to` is the step it would land on. */
export type Wiring = {
  from: string;
  output: OutputId;
  to: string | null;
};

export type Removed = {
  step: Step;
  index: number;
  wires: Wire[];
};

export type PublishState = 'draft' | 'publishing' | 'live';

export type BuilderState = {
  steps: Step[];
  wires: Wire[];
  selectedId: string | null;
  isInspectorOpen: boolean;
  wiring: Wiring | null;
  /** The step Undo brings back, with the wires it had. */
  removed: Removed | null;
  publish: PublishState;
  /** The last change, said to screen readers. */
  notice: string;
};

export type BuilderAction =
  | { type: 'selected'; id: string | null }
  | { type: 'opened'; id: string }
  | { type: 'closed' }
  | { type: 'renamed'; id: string; name: string }
  | { type: 'fieldChanged'; id: string; field: FieldId; value: string }
  | { type: 'wireStarted'; from: string; output: OutputId }
  | { type: 'wireAimed'; to: string | null }
  | { type: 'wireDropped' }
  | { type: 'wireCancelled' }
  | { type: 'connected'; from: string; output: OutputId; to: string }
  | { type: 'disconnected'; from: string; output: OutputId }
  | { type: 'moved'; id: string; cell: Cell }
  | { type: 'removed'; id: string }
  | { type: 'undone' }
  | { type: 'undoDismissed' }
  | { type: 'publishStarted' }
  | { type: 'publishDone' }
  | { type: 'restored' };

type Beat = SessionStep<BuilderState, BuilderAction>;

function placed(link: Connection): Wire {
  return { ...link, arrival: 'placed' };
}

/** The connection an action names, without the action's own fields. */
function linkOf(action: Connection): Connection {
  return { from: action.from, output: action.output, to: action.to };
}

export const INITIAL: BuilderState = {
  steps: STEPS,
  wires: CONNECTIONS.map(placed),
  selectedId: null,
  isInspectorOpen: false,
  wiring: null,
  removed: null,
  publish: 'draft',
  notice: '',
};

export function graphOf(state: BuilderState): Graph {
  return { steps: state.steps, connections: state.wires };
}

function problemsWordOf(count: number) {
  if (count === 1) {
    return '1 problem';
  }
  return `${count} problems`;
}

function isFromOutput(wire: Wire, from: string, output: OutputId) {
  return wire.from === from && wire.output === output;
}

function touches(wire: Wire, id: string) {
  return wire.from === id || wire.to === id;
}

function selected(state: BuilderState, id: string | null): BuilderState {
  if (id === null) {
    return { ...state, selectedId: null, isInspectorOpen: false };
  }
  if (!stepOf(state.steps, id)) {
    return state;
  }
  return { ...state, selectedId: id };
}

function opened(state: BuilderState, id: string): BuilderState {
  if (!stepOf(state.steps, id)) {
    return state;
  }
  return { ...state, selectedId: id, isInspectorOpen: true };
}

function withStep(
  state: BuilderState,
  id: string,
  change: (step: Step) => Step
): BuilderState {
  const steps = state.steps.map((step) => {
    if (step.id === id) {
      return change(step);
    }
    return step;
  });
  return { ...state, steps, publish: 'draft', notice: '' };
}

function fieldChanged(
  state: BuilderState,
  id: string,
  field: FieldId,
  value: string
) {
  return withStep(state, id, (step) => ({
    ...step,
    values: { ...step.values, [field]: value },
  }));
}

function wireStarted(
  state: BuilderState,
  from: string,
  output: OutputId
): BuilderState {
  const source = stepOf(state.steps, from);
  const hasOutput =
    source !== undefined && OUTPUTS_OF[source.kind].includes(output);
  if (!hasOutput) {
    return state;
  }
  return { ...state, wiring: { from, output, to: null } };
}

function wireAimed(state: BuilderState, to: string | null): BuilderState {
  const wiring = state.wiring;
  if (!wiring) {
    return state;
  }
  let target = to;
  if (to !== null && !canConnect(graphOf(state), wiring.from, to)) {
    target = null;
  }
  if (target === wiring.to) {
    return state;
  }
  return { ...state, wiring: { ...wiring, to: target } };
}

function connectedTo(
  state: BuilderState,
  link: Connection,
  arrival: Arrival
): BuilderState {
  const source = stepOf(state.steps, link.from);
  const target = stepOf(state.steps, link.to);
  if (!source || !target) {
    return state;
  }
  const hasOutput = OUTPUTS_OF[source.kind].includes(link.output);
  const isAllowed = hasOutput && canConnect(graphOf(state), link.from, link.to);
  const isSame = targetOf(state.wires, link.from, link.output) === link.to;
  if (!isAllowed || isSame) {
    return state;
  }
  const others = state.wires.filter(
    (wire) => !isFromOutput(wire, link.from, link.output)
  );
  const word = OUTPUT_WORD[link.output];
  const sourceName = shownNameOf(source);
  const targetName = shownNameOf(target);
  return {
    ...state,
    wires: [...others, { ...link, arrival }],
    publish: 'draft',
    notice: `${sourceName}: ${word} now leads to ${targetName}`,
  };
}

function wireDropped(state: BuilderState): BuilderState {
  const wiring = state.wiring;
  if (!wiring) {
    return state;
  }
  const released = { ...state, wiring: null };
  if (wiring.to === null) {
    return released;
  }
  const link = { from: wiring.from, output: wiring.output, to: wiring.to };
  return connectedTo(released, link, 'dropped');
}

function disconnected(
  state: BuilderState,
  from: string,
  output: OutputId
): BuilderState {
  const source = stepOf(state.steps, from);
  const wires = state.wires.filter((wire) => !isFromOutput(wire, from, output));
  const hasChanged = wires.length !== state.wires.length;
  if (!source || !hasChanged) {
    return state;
  }
  const word = OUTPUT_WORD[output];
  return {
    ...state,
    wires,
    publish: 'draft',
    notice: `${shownNameOf(source)}: ${word} leads nowhere now`,
  };
}

function moved(state: BuilderState, id: string, cell: Cell): BuilderState {
  const step = stepOf(state.steps, id);
  const isSamePlace = step?.level === cell.level && step.lane === cell.lane;
  if (!step || isSamePlace) {
    return state;
  }
  const steps = state.steps.map((candidate) => {
    if (candidate.id === id) {
      return { ...candidate, level: cell.level, lane: cell.lane };
    }
    return candidate;
  });
  return { ...state, steps };
}

function removed(state: BuilderState, id: string): BuilderState {
  const index = state.steps.findIndex((step) => step.id === id);
  const step = state.steps[index];
  if (!step) {
    return state;
  }
  const cut = state.wires.filter((wire) => touches(wire, id));
  const kept = state.wires.filter((wire) => !touches(wire, id));
  const steps = state.steps.filter((candidate) => candidate.id !== id);
  const cleared = { ...state, steps, wires: kept, wiring: null };
  const wasSelected = state.selectedId === id;
  let next: BuilderState = cleared;
  if (wasSelected) {
    next = { ...cleared, selectedId: null, isInspectorOpen: false };
  }
  return {
    ...next,
    removed: { step, index, wires: cut },
    publish: 'draft',
    notice: `${shownNameOf(step)} removed. Undo is available`,
  };
}

/** A wire comes back with its step only where it still fits: its port may have been used since. */
function rewired(state: BuilderState, wire: Wire): BuilderState {
  const isFree = targetOf(state.wires, wire.from, wire.output) === null;
  const fits = isFree && canConnect(graphOf(state), wire.from, wire.to);
  if (!fits) {
    return state;
  }
  return { ...state, wires: [...state.wires, placed(wire)] };
}

function undone(state: BuilderState): BuilderState {
  const lost = state.removed;
  if (!lost) {
    return state;
  }
  const steps = [...state.steps];
  steps.splice(lost.index, 0, lost.step);
  let next: BuilderState = { ...state, steps, removed: null };
  for (const wire of lost.wires) {
    next = rewired(next, wire);
  }
  return {
    ...next,
    selectedId: lost.step.id,
    publish: 'draft',
    notice: `${shownNameOf(lost.step)} is back`,
  };
}

/** Publish refuses a workflow with problems and opens the first one, so the way on is in view. */
function refused(state: BuilderState, problems: Problem[]): BuilderState {
  const [first] = problems;
  const step = stepOf(state.steps, first.stepId);
  if (!step) {
    return state;
  }
  const count = problemsWordOf(problems.length);
  const name = shownNameOf(step);
  return {
    ...state,
    selectedId: step.id,
    isInspectorOpen: true,
    notice: `${count} to fix before publishing. ${name}: ${first.line}`,
  };
}

function publishStarted(state: BuilderState): BuilderState {
  const problems = problemsOf(graphOf(state));
  if (problems.length > 0) {
    return refused(state, problems);
  }
  if (state.publish !== 'draft') {
    return state;
  }
  return { ...state, publish: 'publishing', removed: null, notice: '' };
}

function publishDone(state: BuilderState): BuilderState {
  if (state.publish !== 'publishing') {
    return state;
  }
  return {
    ...state,
    publish: 'live',
    notice: 'Published. The workflow is live',
  };
}

export function reducer(
  state: BuilderState,
  action: BuilderAction
): BuilderState {
  switch (action.type) {
    case 'selected':
      return selected(state, action.id);
    case 'opened':
      return opened(state, action.id);
    case 'closed':
      return { ...state, isInspectorOpen: false };
    case 'renamed':
      return withStep(state, action.id, (step) => ({
        ...step,
        name: action.name,
      }));
    case 'fieldChanged':
      return fieldChanged(state, action.id, action.field, action.value);
    case 'wireStarted':
      return wireStarted(state, action.from, action.output);
    case 'wireAimed':
      return wireAimed(state, action.to);
    case 'wireDropped':
      return wireDropped(state);
    case 'wireCancelled':
      return { ...state, wiring: null };
    case 'connected':
      return connectedTo(state, linkOf(action), 'drawn');
    case 'disconnected':
      return disconnected(state, action.from, action.output);
    case 'moved':
      return moved(state, action.id, action.cell);
    case 'removed':
      return removed(state, action.id);
    case 'undone':
      return undone(state);
    case 'undoDismissed':
      return { ...state, removed: null };
    case 'publishStarted':
      return publishStarted(state);
    case 'publishDone':
      return publishDone(state);
    case 'restored':
      return { ...INITIAL, notice: 'The sample workflow is back' };
  }
}

/** How long publishing takes before the workflow is live. */
export const PUBLISH_MS = 1400;

const CONNECTING: Beat[] = [
  {
    after: 1700,
    by: 'demo',
    press: 'port-size-no',
    action: { type: 'wireStarted', from: 'size', output: 'no' },
  },
  { after: 520, by: 'demo', action: { type: 'wireAimed', to: 'welcome' } },
  { after: 900, by: 'demo', action: { type: 'wireDropped' } },
];

/** One problem is left, so this press is refused and opens the step that has it. */
const REFUSED: Beat = {
  after: 1500,
  by: 'demo',
  press: 'publish',
  action: { type: 'publishStarted' },
};

/** The text arrives a few letters at a time: the whole builder renders again on each beat. */
const TYPED_LETTERS = 3;

function typedTextsOf(text: string) {
  const prefixes = prefixesOf(text);
  const last = prefixes.length - 1;
  return prefixes.filter((_, index) => {
    const endsGroup = index % TYPED_LETTERS === TYPED_LETTERS - 1;
    return endsGroup || index === last;
  });
}

function typingBeatOf(value: string, index: number): Beat {
  return {
    after: keyDelayOf(index, 1300, 96),
    by: 'demo',
    action: {
      type: 'fieldChanged',
      id: 'enrich',
      field: 'instructions',
      value,
    },
  };
}

const TYPING = typedTextsOf(DEMO_INSTRUCTIONS).map(typingBeatOf);

/** The last step is the system's answer, so it plays even once a person has taken over. */
const PUBLISHING: Beat[] = [
  {
    after: 1100,
    by: 'demo',
    press: 'publish',
    action: { type: 'publishStarted' },
  },
  { after: PUBLISH_MS, action: { type: 'publishDone' } },
];

export const SCRIPT: Beat[] = [
  ...CONNECTING,
  REFUSED,
  ...TYPING,
  ...PUBLISHING,
];

/**
 * Under reduced motion the builder rests on the most telling moment: every wire in place, one
 * problem left and the inspector open on the field that has it.
 */
function restingOf() {
  let state = INITIAL;
  for (const beat of [...CONNECTING, REFUSED]) {
    state = reducer(state, beat.action);
  }
  return { ...state, wires: state.wires.map(placed), notice: '' };
}

export const RESTING = restingOf();

